const int MAXNODES = 1000010;
const LL MODULUS = 1000000007;
bool visited_nodes[MAXNODES];

int main() {
    int p_value, k_value, inverse_k;
    scanf("%d%d", &p_value, &k_value);
    LL answer = 1;
    if (k_value != 0) {
        if (k_value == 1) answer = p_value;
        for (int i=1; i<p_value; i++) {
