                inverse_k = i;
                break;
            }
        }
        for (int i=1; i<p_value; i++) {
            if (!visited_nodes[i]) {
                visited_nodes[i] = true;
                int count = 1;
                int j = (LL)k_value * i % p_value;
                int m = inverse_k;
                while (!visited_nodes[j]) {
                    visited_nodes[j] = true;
                    count++;
                    m = (LL)m * inverse_k % p_value;
                    j = (LL)k_value * j % p_value;
