                if (m == 1) answer = (LL)answer * p_value % MODULUS;
            }
        }
    } else {
        for (int i=1; i<p_value; i++) answer = (LL)answer * p_value % MODULUS;
    }
    cout << answer << endl;
    return 0;
}
